// TEMP DEBUG: wide window test
const HOURS_BACK = 24 * 30; // 30 days, to sanity-check the query mechanism

const end = new Date();
const start = new Date(end.getTime() - HOURS_BACK * 60 * 60 * 1000);

function arxivUtc(d) {
  const yyyy = d.getUTCFullYear();
  const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(d.getUTCDate()).padStart(2, "0");
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const mi = String(d.getUTCMinutes()).padStart(2, "0");
  return `${yyyy}${mm}${dd}${hh}${mi}`;
}

const date_from = arxivUtc(start);
const date_to = arxivUtc(end);

const domain = "gr-qc";
const label = "General Relativity and Quantum Cosmology";

const query = `cat:${domain} AND submittedDate:[${date_from} TO ${date_to}]`;

return [{
  json: {
    domain,
    label,
    date: date_to.slice(0, 8),
    date_from,
    date_to,
    query
  }
}];

// ============================================================
// GR-QC — Parse arXiv "new" LISTING PAGE + Keyword Gate (FIXED)
// ============================================================
//
// ROOT CAUSE OF "zero output every run":
// The old version queried export.arxiv.org/api's search index by
// submittedDate. That index lags the real /list/gr-qc/new page by
// multiple days (verified live: it did not yet contain today's
// "Naked Singularities beyond Spherical Symmetry" paper, only
// papers up to ~3 days old). No client-side date window could fix
// that -- the upstream index itself was stale.
//
// FIX: parse the exact HTML page a human checks at
// https://arxiv.org/list/gr-qc/new -- this is always accurate for
// "today", with zero date-window math needed on our side.
//
// Also: keyword matching now tolerates plural/hyphenated forms
// ("naked singularities", "naked-singularity"), not only the exact
// literal phrase "naked singularity" -- today's real matching paper
// used the plural form, which the old exact-substring check missed.
// ============================================================

const input = items[0]?.json ?? {};
let html = input.data ?? input.body ?? input.response ?? input.html ?? '';
if (typeof html !== 'string' || html.trim() === '') {
  return [];
}

function decodeEntities(text) {
  return String(text || '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)));
}

function stripTags(text) {
  return decodeEntities(String(text || ''))
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// ------------------------------------------------------------
// Isolate the "New submissions" section only. Cross-lists and
// Replacements are deliberately excluded -- a paper that only
// mentions a keyword because an OLDER paper was revised today is
// not a new paper.
// ------------------------------------------------------------

function extractSection(fullHtml, sectionName) {
  const re = new RegExp(
    `<h3>\\s*${sectionName}[^<]*</h3>([\\s\\S]*?)(?:<dl id=['"]articles['"]>|$)`,
    'i'
  );
  const m = fullHtml.match(re);
  return m ? m[1] : '';
}

const newSection = extractSection(html, 'New submissions');
if (!newSection) {
  return [];
}

// ------------------------------------------------------------
// Announcement date, for published/updated fields
// ------------------------------------------------------------

let announceIso = new Date().toISOString();
const dateHeaderMatch = html.match(/Showing new listings for [^<]*?(\d{1,2} [A-Za-z]+ \d{4})/);
if (dateHeaderMatch) {
  const parsed = new Date(dateHeaderMatch[1] + ' UTC');
  if (!isNaN(parsed.getTime())) {
    announceIso = parsed.toISOString();
  }
}

// ------------------------------------------------------------
// Extract each <dt>...</dt><dd>...</dd> paper entry
// ------------------------------------------------------------

const entryRe = /<dt>([\s\S]*?)<\/dt>\s*<dd>([\s\S]*?)<\/dd>/g;
const papers = [];
let m;
while ((m = entryRe.exec(newSection)) !== null) {
  const dt = m[1];
  const dd = m[2];

  const idMatch = dt.match(/href\s*=\s*"\/abs\/([^"]+)"/);
  if (!idMatch) continue;
  const arxivId = idMatch[1].trim();

  const titleMatch = dd.match(/list-title[^>]*>\s*<span class=['"]descriptor['"]>Title:<\/span>([\s\S]*?)<\/div>/i);
  const title = titleMatch ? stripTags(titleMatch[1]) : '';
  if (!title) continue;

  const authorsMatch = dd.match(/list-authors['"]>([\s\S]*?)<\/div>/i);
  let authors = [];
  if (authorsMatch) {
    authors = [...authorsMatch[1].matchAll(/<a[^>]*>([^<]*)<\/a>/g)]
      .map(a => decodeEntities(a[1]).trim())
      .filter(Boolean);
  }

  const abstractMatch = dd.match(/<p class=['"]mathjax['"]>([\s\S]*?)<\/p>/i);
  const abstract = abstractMatch ? stripTags(abstractMatch[1]) : '';

  papers.push({
    arxiv_id: arxivId,
    title,
    abstract,
    authors,
    published: announceIso,
    updated: announceIso,
    arxiv_url: `https://arxiv.org/abs/${arxivId}`,
    pdf_url: `https://arxiv.org/pdf/${arxivId}`
  });
}

// ------------------------------------------------------------
// Keyword gate -- tolerant regex variants of the two required
// phrases, still hard-gated: no match = dropped entirely.
// ------------------------------------------------------------

const KEYWORD_PATTERNS = [
  { label: 'energy extraction', re: /energy\s+extraction/i },
  { label: 'naked singularity', re: /naked[\s-]+singularit(?:y|ies)/i }
];

const output = [];
for (const p of papers) {
  const titleMatches = KEYWORD_PATTERNS.filter(k => k.re.test(p.title)).map(k => k.label);
  const abstractMatches = KEYWORD_PATTERNS.filter(k => k.re.test(p.abstract)).map(k => k.label);
  const matchedKeywords = [...new Set([...titleMatches, ...abstractMatches])];

  if (matchedKeywords.length === 0) continue;

  output.push({
    json: {
      domain: 'gr-qc',
      arxiv_id: p.arxiv_id,
      title: p.title,
      abstract: p.abstract,
      authors: p.authors,
      published: p.published,
      updated: p.updated,
      arxiv_url: p.arxiv_url,
      pdf_url: p.pdf_url,
      matched_keywords: matchedKeywords,
      title_keyword_matches: titleMatches,
      abstract_keyword_matches: abstractMatches,
      keyword_match_count: matchedKeywords.length
    }
  });
}

return output;

