  paperText = paperText.slice(0, MAX_CHARS);
  truncatedNote = `\n\n[Note: paper text truncated to the first ${MAX_CHARS} characters (abstract, introduction, and start of the derivation) to keep analysis fast. Later sections were not seen.]`;
}

const analysis_prompt = `You are a physics research assistant summarizing a gr-qc paper for a technical reader.

PAPER METADATA
Title: ${meta.title}
Authors: ${meta.authors.join(', ')}
arXiv: ${meta.arxiv_url}
Matched keywords: ${meta.matched_keywords.join(', ')}

PAPER TEXT (excerpt)
================
${paperText}
================${truncatedNote}

TASK
Write a compact technical walkthrough of THIS paper, grounded only in the excerpt above. Do not independently rederive results from scratch -- instead, explain the derivation and reasoning the paper itself lays out, step by step, in plain language, filling in only short/obvious intermediate algebra the paper skips.

IMPORTANT: Output ONLY the four numbered sections below, starting immediately with "1. Problem & motivation". Do not show your reasoning, do not add a preamble, do not restate these instructions, and do not write anything before section 1 or after section 4. Number the sections literally as 1, 2, 3, 4 (never repeat "1." for later sections). Keep section 1 to at most 60 words, section 2 to at most 150 words, section 3 to at most 250 words, and section 4 to at most 140 words, so the full answer finishes well inside the 600-word budget and every section is complete.

Structure, using these exact headers, and keep the ENTIRE response under 600 words total:
1. Problem & motivation (1-2 sentences)
2. Setup & key definitions (the objects, assumptions, starting equations the paper introduces)
3. Walkthrough of the derivation/argument as presented (step by step, in the paper's own logical order)
4. Main result and what it means

Rules: use only what is in the excerpt; if the excerpt cuts off mid-argument, say so plainly rather than inventing the rest; use clean LaTeX notation for any equations; be concise, not exhaustive.`;

return [{
  json: {
    ...meta,
    full_paper_text: paperText,
    analysis_prompt
  }
}];

