const staticData = $getWorkflowStaticData('global');
staticData.pending = staticData.pending || {};

const response = $input.first().json;
const updates = response.result || [];

let maxUpdateId = staticData.telegramOffset ? staticData.telegramOffset - 1 : 0;
const out = [];

for (const upd of updates) {
  if (upd.update_id >= maxUpdateId) maxUpdateId = upd.update_id;
  const msg = upd.message;
  if (!msg || !msg.text) continue;

  const text = String(msg.text).trim();
  const m = text.match(/^(yes|no)\s+(\S+)/i);
  if (!m) continue;

  const action = m[1].toLowerCase();
  const arxivId = m[2];
  const chatId = msg.chat.id;

  let foundKey = null;
  let domain = null;
  for (const key of Object.keys(staticData.pending)) {
    const idx = key.indexOf('|');
    const d = key.slice(0, idx);
    const id = key.slice(idx + 1);
    if (id === arxivId) { foundKey = key; domain = d; break; }
  }

  if (!foundKey) {
    out.push({ json: { kind: 'reply', chat_id: chatId, text: `No pending paper found for ${arxivId}.` } });
    continue;
  }

  const entry = staticData.pending[foundKey];
  if (entry.status !== 'pending') {
    out.push({ json: { kind: 'reply', chat_id: chatId, text: `Already handled: ${arxivId}.` } });
    continue;
  }

  if (action === 'no') {
    entry.status = 'declined';
    out.push({ json: { kind: 'reply', chat_id: chatId, text: `Skipped: ${arxivId}.` } });
  } else if (action === 'yes') {
    entry.status = 'in_progress';
    out.push({ json: { kind: 'reply', chat_id: chatId, text: `Analyzing ${arxivId} — this will take a few minutes...` } });
    out.push({ json: { kind: 'analyze', domain, ...entry.meta } });
  }
}

staticData.telegramOffset = maxUpdateId + 1;

if (out.length === 0) {
  return [{ json: { kind: 'none' } }];
}
return out;
